  "Stripe est l'une des plus grandes et des plus fiables sociétés de paiement au monde. Elle gère en toute sécurité les paiements en ligne de millions d'entreprises, du commerce de quartier à Amazon, Google et Shopify. Yuno utilise Stripe pour que vos clients paient en sécurité et que vous soyez payé de façon fiable.": "Stripe es una de las empresas de pago más grandes y fiables del mundo. Gestiona de forma segura los pagos en línea de millones de negocios, desde el comercio de barrio hasta Amazon, Google y Shopify. Yuno usa Stripe para que tus clientes paguen con seguridad y tú cobres de forma fiable.",
  "Stripe est un établissement de paiement agréé et réglementé en Europe et aux États-Unis, avec une sécurité de niveau bancaire (certifié PCI-DSS). Les données de carte sont chiffrées et ne passent jamais par Yuno.": "Stripe es una entidad de pago autorizada y regulada en Europa y Estados Unidos, con seguridad de nivel bancario (certificada PCI-DSS). Los datos de la tarjeta se cifran y nunca pasan por Yuno.",
