  'hype.basedOn': 'Basado en el interés actual, engagement y conversión.',
  'hype.tooltip': 'El Hype Score no es una nota. Es un indicador de preparación del evento que te ayuda a entender si el evento está tomando impulso y qué puedes hacer para mejorarlo.',
  'hype.whyThisLevel': '¿Por qué este nivel?',
  'hype.whatYouCanTest': 'Lo que puedes probar',
  'hype.ourInsight': 'Nuestra lectura',
  'hype.scoreBreakdown': 'Desglose del score',
  'hype.howItWorks': '¿Cómo se calcula la previsión?',
  'hype.howItWorksContent1': 'La previsión responde a una pregunta: con lo que tienes ahora, ¿qué tan lleno estará la noche?',
  'hype.howItWorksContent2': 'Paso 1 — Ritmo. En la noche las ventas se concentran al final (la mayoría de entradas se venden en los últimos días). Aprendemos la curva típica de tus eventos pasados y comparamos tus ventas actuales con donde "deberían" estar en esta etapa de la cuenta atrás.',
  'hype.howItWorksContent3': 'Paso 2 — Demanda. Leemos las señales que preceden a una compra: tráfico vs tu día normal, el embudo vista → carrito → checkout → compra, tiempo en página, visitantes recurrentes, favoritos y fuentes de tráfico. Esto ajusta la proyección hacia arriba o abajo.',
  'hype.howItWorksContent4': 'Paso 3 — Confianza. Una estimación a 30 días es frágil; una proyección la víspera es fiable. La confianza crece con el tiempo transcurrido, el número de eventos pasados y el volumen de datos.',
  'hype.howItWorksContent5': 'Los 5 pilares (Interés, Engagement, Conversión, Recurrencia, Momentum) desglosan el score en partes accionables, cada una con su checklist.',
  'hype.howItWorksContent6': 'Cuantos más eventos hagas, más inteligente será la previsión: aprende el ritmo propio de tu local.',
