  'plan.stripeAboutIntro': 'Stripe es una de las empresas de pagos más grandes y confiables del mundo. Gestiona de forma segura los pagos en línea de millones de negocios, desde tiendas locales hasta Amazon, Google y Shopify. Yuno usa Stripe para que tus clientes paguen con seguridad y tú cobres de forma fiable.',
